def checked_rows(self):
    """
    A generator which yields rows which are ready to write to output.
    """
    length = len(self.column_names)
    line_number = self.reader.line_num
    joinable_row_errors = []

    for row in self.reader:
        try:
            if len(row) != length:
                raise LengthMismatchError(line_number, row, length)

            yield row

            # Don't join rows across valid rows.
            joinable_row_errors = []
        except LengthMismatchError as e:
            self.errors.append(e)

            # Don't join with long rows.
            if len(row) > length:
                joinable_row_errors = []
            else:
                joinable_row_errors.append(e)

                while joinable_row_errors:
                    fixed_row = join_rows([error.row for error in joinable_row_errors], joiner=' ')

                    if len(fixed_row) < length:
                        break

                    if len(fixed_row) == length:
                        self.rows_joined += len(joinable_row_errors)
                        self.joins += 1

                        yield fixed_row

                        for fixed in joinable_row_errors:
                            joinable_row_errors.remove(fixed)
                            self.errors.remove(fixed)

                        break

                    # keep trying in case we're too long because of a straggler
                    joinable_row_errors = joinable_row_errors[1:]

        except CSVTestException as e:
            self.errors.append(e)

            # Don't join rows across other errors.
            joinable_row_errors = []

        line_number = self.reader.line_num

def __call__(self, row):
    """
    Return a tuple (column, start, length) based on this instance's
    parameters. If the first time this is called, the row's 'start'
    value is 1, then all 'start' values including the first will be one
    less than in the actual input data, to adjust for one-based
    specifications.  Values for 'start' and 'length' will be cast to
    integers.
    """
    if self.one_based is None:
        self.one_based = int(row[self.start]) == 1

    if self.one_based:
        adjusted_start = int(row[self.start]) - 1
    else:
        adjusted_start = int(row[self.start])

    return FixedWidthField(row[self.column], adjusted_start, int(row[self.length]))

def generate_feature_collection(self, table):
    features = []
    bounds = self.GeoJsonBounds()

    for row in table.rows:
        feature = self.feature_for_row(row)

        if not self.args.no_bbox:
            bounds.add_feature(feature)

        features.append(feature)

    items = [
        ('type', 'FeatureCollection'),
        ('features', features),
    ]

    if not self.args.no_bbox:
        items.insert(1, ('bbox', bounds.bbox()))

    if self.args.crs:
        items.append(('crs', OrderedDict([
            ('type', 'name'),
            ('properties', {
                'name': self.args.crs,
            }),
        ])))

    return OrderedDict(items)

def feature_for_row(self, row):
    feature = OrderedDict([
        ('type', 'Feature'),
        ('properties', OrderedDict()),
    ])

    for i, c in enumerate(row):
        # Prevent "type" or geo fields from being added to properties.
        if c is None or i in (self.type_column, self.lat_column, self.lon_column, self.geometry_column):
            continue
        if i == self.id_column:
            feature['id'] = c
        elif c:
            feature['properties'][self.column_names[i]] = c

    feature['geometry'] = self.geometry_for_row(row)

    return feature

def geometry_for_row(self, row):
    lat = None
    lon = None

    if self.geometry_column is not None:
        return json.loads(row[self.geometry_column])

    if self.lat_column is not None and self.lon_column is not None:
        try:
            lon = float(row[self.lon_column])
            lat = float(row[self.lat_column])
        except ValueError:
            lon = None
            lat = None

    if lon and lat:
        return OrderedDict([
            ('type', 'Point'),
            ('coordinates', [lon, lat]),
        ])

