def geojson2csv(f, key=None, **kwargs):
    """
    Convert a GeoJSON document into CSV format.
    """
    js = json.load(f, object_pairs_hook=OrderedDict)

    if not isinstance(js, dict):
        raise TypeError('JSON document is not valid GeoJSON: Root element is not an object.')

    if 'type' not in js:
        raise TypeError('JSON document is not valid GeoJSON: No top-level "type" key.')

    if js['type'] != 'FeatureCollection':
        raise TypeError(f"Only GeoJSON with root FeatureCollection type is supported. Not {js['type']}")

    if 'features' not in js:
        raise TypeError('JSON document is not a valid FeatureCollection: No top-level "features" key.')

    features = js['features']

    features_parsed = []    # tuples in the format (id, properties, geometry)
    property_fields = []

    for feature in features:
        properties = feature.get('properties', {})

        for prop in properties.keys():
            if prop not in property_fields:
                property_fields.append(prop)

        geometry = feature['geometry']
        if geometry:
            geometry_type = geometry.get('type')
        else:
            geometry_type = None
        if geometry_type == 'Point' and 'coordinates' in geometry:
            longitude, latitude = geometry['coordinates'][0:2]  # Drop altitude or elevation.
        else:
            longitude, latitude = (None, None)

        features_parsed.append((feature.get('id'), properties, json.dumps(
            geometry), geometry_type, longitude, latitude))

    header = ['id']
    header.extend(property_fields)
    header.extend(('geojson', 'type', 'longitude', 'latitude'))

    o = StringIO()
    writer = agate.csv.writer(o)

    writer.writerow(header)

    for geoid, properties, geometry, geometry_type, longitude, latitude in features_parsed:
        row = [geoid]

        for field in property_fields:
            value = properties.get(field)
            if isinstance(value, OrderedDict):
                value = json.dumps(value)
            row.append(value)

        row.extend((geometry, geometry_type, longitude, latitude))

        writer.writerow(row)

    output = o.getvalue()
    o.close()

    return output

def open_excel_input_file(self, path):
    if not path or path == '-':
        return BytesIO(sys.stdin.buffer.read())
    return open(path, 'rb')

def main(self):
    path = self.args.input_path

    # Determine the file type.
    if self.args.filetype:
        filetype = self.args.filetype
    elif self.args.schema:
        filetype = 'fixed'
    elif self.args.key:
        filetype = 'json'
    else:
        if not path or path == '-':
            self.argparser.error('You must specify a format when providing input as piped data via STDIN.')
        filetype = convert.guess_format(path)
        if not filetype:
            self.argparser.error('Unable to automatically determine the format of the input file. Try specifying '
                                 'a format with --format.')

    if self.args.names_only:
        if filetype in ('xls', 'xlsx'):
            sheets = self.sheet_names(path, filetype)
            for sheet in sheets:
                self.output_file.write(f'{sheet}\n')
        else:
            self.argparser.error('You cannot use the -n or --names options with non-Excel files.')
        return

    # Set the input file.
    if filetype in ('xls', 'xlsx'):
        self.input_file = self.open_excel_input_file(path)
    else:
        self.input_file = self._open_input_file(path)

    # Set the reader's arguments.
    kwargs = {}
    sniff_limit = self.args.sniff_limit if self.args.sniff_limit != -1 else None

    if self.args.schema:
        schema = self._open_input_file(self.args.schema)
    elif filetype == 'fixed':
        raise ValueError('schema must not be null when format is "fixed"')

    if filetype == 'csv':
        kwargs.update(self.reader_kwargs)
        kwargs['sniff_limit'] = sniff_limit

    if filetype in ('xls', 'xlsx'):
        kwargs['header'] = not self.args.no_header_row

    if filetype not in ('dbf', 'geojson', 'json', 'ndjson'):  # csv, fixed, xls, xlsx
        kwargs['skip_lines'] = self.args.skip_lines

    if filetype != 'dbf':
        kwargs['column_types'] = self.get_column_types()

    # Convert the file.
    if (
        filetype == 'csv'
        and self.args.no_inference
        and not self.args.no_header_row
        and not self.args.skip_lines
        and sniff_limit == 0
    ):
        reader = agate.csv.reader(self.input_file, **self.reader_kwargs)
        writer = agate.csv.writer(self.output_file, **self.writer_kwargs)
        writer.writerows(reader)
    elif filetype == 'fixed':
        self.output_file.write(fixed2csv(self.input_file, schema, output=self.output_file, **kwargs))
    elif filetype == 'geojson':
        self.output_file.write(geojson2csv(self.input_file, **kwargs))
    elif filetype in ('csv', 'dbf', 'json', 'ndjson', 'xls', 'xlsx'):
        if filetype == 'csv':
            table = agate.Table.from_csv(self.input_file, **kwargs)
        elif filetype == 'json':
            table = agate.Table.from_json(self.input_file, key=self.args.key, **kwargs)
        elif filetype == 'ndjson':
            table = agate.Table.from_json(self.input_file, key=self.args.key, newline=True, **kwargs)
        elif filetype == 'xls':
            table = agate.Table.from_xls(self.input_file, sheet=self.args.sheet,
                                         encoding_override=self.args.encoding_xls, **kwargs)
        elif filetype == 'xlsx':
            table = agate.Table.from_xlsx(self.input_file, sheet=self.args.sheet, **kwargs)
        elif filetype == 'dbf':
            if not hasattr(self.input_file, 'name'):
                raise ValueError('DBF files can not be converted from stdin. You must pass a filename.')
            table = agate.Table.from_dbf(self.input_file.name, **kwargs)
        table.to_csv(self.output_file, **self.writer_kwargs)

    if self.args.write_sheets:
        # Close and re-open the file, as the file object has been mutated or closed.
        self.input_file.close()

        self.input_file = self.open_excel_input_file(path)

        if self.args.write_sheets == '-':
            sheets = self.sheet_names(path, filetype)
        else:
            sheets = [int(sheet) if sheet.isdigit() else sheet for sheet in self.args.write_sheets.split(',')]

        if filetype == 'xls':
            tables = agate.Table.from_xls(self.input_file, sheet=sheets,
                                          encoding_override=self.args.encoding_xls, **kwargs)
        elif filetype == 'xlsx':
            tables = agate.Table.from_xlsx(self.input_file, sheet=sheets, **kwargs)

        base = splitext(self.input_file.name)[0]
        for i, (sheet_name, table) in enumerate(tables.items()):
            if self.args.use_sheet_names:
                filename = '%s_%s.csv' % (base, sheet_name)
            else:
                filename = '%s_%d.csv' % (base, i)
            with open(filename, 'w') as f:
                table.to_csv(f, **self.writer_kwargs)

    self.input_file.close()

    if self.args.schema:
        schema.close()

def _extract_csv_reader_kwargs(self):
    """
    Extracts those from the command-line arguments those would should be passed through to the input CSV reader(s).
    """
    kwargs = {}

    if self.args.tabs:
        kwargs['delimiter'] = '\t'
    elif self.args.delimiter:
        kwargs['delimiter'] = self.args.delimiter

    for arg in ('quotechar', 'quoting', 'doublequote', 'escapechar', 'field_size_limit', 'skipinitialspace'):
        value = getattr(self.args, arg)
        if value is not None:
            kwargs[arg] = value

    if getattr(self.args, 'no_header_row', None):
        kwargs['header'] = not self.args.no_header_row

    return kwargs

def _extract_csv_writer_kwargs(self):
    """
    Extracts those from the command-line arguments those would should be passed through to the output CSV writer.
    """
    kwargs = {}

    if getattr(self.args, 'line_numbers', None):
        kwargs['line_numbers'] = True

    return kwargs

def run(self):
    """
    A wrapper around the main loop of the utility which handles opening and
    closing files.
    """
    if 'f' not in self.override_flags:
        self.input_file = self._open_input_file(self.args.input_path)

    try:
        with warnings.catch_warnings():
            if getattr(self.args, 'no_header_row', None):
                warnings.filterwarnings(action='ignore', message='Column names not specified', module='agate')

            self.main()
    finally:
        if 'f' not in self.override_flags:
            self.input_file.close()

