def _open_input_file(self, path, opened=False):
    """
    Open the input file specified on the command line.
    """
    if not path or path == '-':
        # "UnsupportedOperation: It is not possible to set the encoding or newline of stream after the first read"
        if not opened:
            sys.stdin.reconfigure(encoding=self.args.encoding)
        f = sys.stdin
    else:
        extension = splitext(path)[1]

        if extension == '.gz':
            func = gzip.open
        elif extension == '.bz2':
            func = bz2.open
        elif extension == ".xz":
            func = lzma.open
        else:
            func = open

        f = LazyFile(func, path, mode='rt', encoding=self.args.encoding)

    return f

def get_column_types(self):
    if getattr(self.args, 'blanks', None):
        type_kwargs = {'null_values': []}
    else:
        type_kwargs = {'null_values': list(DEFAULT_NULL_VALUES)}
    for null_value in getattr(self.args, 'null_values', []):
        type_kwargs['null_values'].append(null_value)

    text_type = agate.Text(**type_kwargs)

    if self.args.no_inference:
        types = [text_type]
    else:
        number_type = agate.Number(locale=self.args.locale, **type_kwargs)

        # See the order in the `agate.TypeTester` class.
        types = [
            agate.Boolean(**type_kwargs),
            agate.TimeDelta(**type_kwargs),
            agate.Date(date_format=self.args.date_format, **type_kwargs),
            agate.DateTime(datetime_format=self.args.datetime_format, **type_kwargs),
            text_type,
        ]

        # In order to parse dates like "20010101".
        if self.args.date_format or self.args.datetime_format:
            types.insert(-1, number_type)
        else:
            types.insert(1, number_type)

    return agate.TypeTester(types=types)

def get_column_offset(self):
    if self.args.zero_based:
        return 0
    return 1

def skip_lines(self):
    if isinstance(self.args.skip_lines, int):
        while self.args.skip_lines > 0:
            self.input_file.readline()
            self.args.skip_lines -= 1
    else:
        raise ValueError('skip_lines argument must be an int')

    return self.input_file

def get_rows_and_column_names_and_column_ids(self, **kwargs):
    rows = agate.csv.reader(self.skip_lines(), **kwargs)

    try:
        next_row = next(rows)
    except StopIteration:
        return iter([]), [], []

    if self.args.no_header_row:
        # Peek at a row to get the number of columns.
        row = next_row
        rows = itertools.chain([row], rows)
        column_names = make_default_headers(len(row))
    else:
        column_names = next_row

    column_offset = self.get_column_offset()
    if kwargs.get('line_numbers'):
        column_offset -= 1

    column_ids = parse_column_identifiers(
        self.args.columns,
        column_names,
        column_offset,
        getattr(self.args, 'not_columns', None),
    )

    return rows, column_names, column_ids

def print_column_names(self):
    """
    Pretty-prints the names and indices of all columns to a file-like object (usually sys.stdout).
    """
    if getattr(self.args, 'no_header_row', None):
        raise RequiredHeaderError('You cannot use --no-header-row with the -n or --names options.')

    if getattr(self.args, 'zero_based', None):
        start = 0
    else:
        start = 1

    rows = agate.csv.reader(self.skip_lines(), **self.reader_kwargs)
    column_names = next(rows)

    for i, c in enumerate(column_names, start):
        self.output_file.write('%3i: %s\n' % (i, c))

def isatty(f):
    try:
        return f.isatty()
    except ValueError:  # I/O operation on closed file
        return False

def make_default_headers(n):
    """
    Make a set of simple, default headers for files that are missing them.
    """
    return tuple(agate.utils.letter_name(i) for i in range(n))

def main(self):
    if isatty(sys.stdin) and self.args.input_paths == ['-']:
        sys.stderr.write('No input file or piped data provided. Waiting for standard input:\n')

    has_groups = self.args.groups is not None or self.args.group_by_filenames

    if self.args.groups is not None and not self.args.group_by_filenames:
        groups = self.args.groups.split(',')

        if len(groups) != len(self.args.input_paths):
            self.argparser.error(
                'The number of grouping values must be equal to the number of CSV files being stacked.')
    else:
        groups = None

    group_name = self.args.group_name if self.args.group_name else 'group'
    use_fieldnames = not self.args.no_header_row

    if use_fieldnames:
        Reader = agate.csv.DictReader
    else:
        Reader = agate.csv.reader

    headers = []
    stdin_fieldnames = []
    stdin_first_row = []

    for path in self.args.input_paths:
        f = self._open_input_file(path)
        file_is_stdin = path == '-'

        _skip_lines(f, self.args)
        rows = Reader(f, **self.reader_kwargs)

        if use_fieldnames:
            for field in rows.fieldnames:
                if field not in headers:
                    headers.append(field)

            # If the file is standard input, store the fieldnames so that the rows can be read correctly later.
            if file_is_stdin:
                stdin_fieldnames = rows.fieldnames
            else:
                f.close()
        else:
            row = next(rows, [])
            headers = list(make_default_headers(len(row)))

            # If the file is standard input, store the row that was used to calculate the number of columns.
            if file_is_stdin:
                stdin_first_row = row
            else:
                f.close()

            # If we aren't using header rows, we only look at the first file and stack columns in the same order.
            break

    if has_groups:
        headers.insert(0, group_name)

    if use_fieldnames:
        output = agate.csv.DictWriter(self.output_file, fieldnames=headers, **self.writer_kwargs)
        output.writeheader()
    else:
        output = agate.csv.writer(self.output_file, **self.writer_kwargs)
        output.writerow(headers)

    for i, path in enumerate(self.args.input_paths):
        f = self._open_input_file(path, opened=True)
        file_is_stdin = path == '-'

        if has_groups:
            if groups:
                group = groups[i]
            else:
                group = os.path.basename(f.name)

        # If the file is standard input, we've already skipped any lines above, to find its header row.
        if not file_is_stdin:
            _skip_lines(f, self.args)

        # If the file is standard input, we've already read the header row, so we need to provide it here.
        kwargs = {}
        if file_is_stdin and use_fieldnames:
            kwargs['fieldnames'] = stdin_fieldnames

        rows = Reader(f, **self.reader_kwargs, **kwargs)

        # If the file is standard input, we need to add back the row we used to calculate the number of columns.
        if file_is_stdin and stdin_first_row:
            output.writerow(stdin_first_row)

        for row in rows:
            if has_groups:
                if use_fieldnames:
                    row[group_name] = group
                else:
                    row.insert(0, group)

            output.writerow(row)

        f.close()

def main(self):
    if self.additional_input_expected():
