def default_str_decimal(obj):
    if isinstance(obj, (datetime.date, datetime.datetime)):
        return obj.isoformat()
    if isinstance(obj, decimal.Decimal):
        return str(obj)
    raise TypeError(f'{repr(obj)} is not JSON serializable')

def default_float_decimal(obj):
    if isinstance(obj, decimal.Decimal):
        return float(obj)
    return default_str_decimal(obj)

def match_column_identifier(column_names, c, column_offset=1):
    """
    Determine what column a single column id (name or index) matches in a series of column names.
    Note that integer values are *always* treated as positional identifiers. If you happen to have
    column names which are also integers, you must specify them using a positional index.
    """
    if isinstance(c, str) and not c.isdigit() and c in column_names:
        return column_names.index(c)

    try:
        c = int(c) - column_offset
    # Fail out if neither a column name nor an integer
    except ValueError:
        raise ColumnIdentifierError("Column '%s' is invalid. It is neither an integer nor a column name. "
                                    "Column names are: %s" % (c, repr(column_names)[1:-1]))

    # Fail out if index is 0-based
    if c < 0:
        raise ColumnIdentifierError("Column %i is invalid. Columns are 1-based." % (c + column_offset))

    # Fail out if index is out of range
    if c >= len(column_names):
        raise ColumnIdentifierError("Column %i is invalid. The last column is '%s' at index %i." % (
            c + column_offset, column_names[-1], len(column_names) - 1 + column_offset))

    return c

def parse_column_identifiers(ids, column_names, column_offset=1, excluded_columns=None):
    """
    Parse a comma-separated list of column indices AND/OR names into a list of integer indices.
    Ranges of integers can be specified with two integers separated by a '-' or ':' character.
    Ranges of non-integers (e.g. column names) are not supported.
    Note: Column indices are 1-based.
    """
    if not column_names:
        return []

    if not ids and not excluded_columns:
        return range(len(column_names))

    if ids:
        columns = []

        for c in ids.split(','):
            try:
                columns.append(match_column_identifier(column_names, c, column_offset))
            except ColumnIdentifierError:
                if ':' in c:
                    a, b = c.split(':', 1)
                elif '-' in c:
                    a, b = c.split('-', 1)
                else:
                    raise

                try:
                    a = int(a) if a else 1
                    b = int(b) + 1 if b else len(column_names) + 1
                except ValueError:
                    raise ColumnIdentifierError(
                        "Invalid range %s. Ranges must be two integers separated by a - or : character.")

                for x in range(a, b):
                    columns.append(match_column_identifier(column_names, x, column_offset))
    else:
        columns = range(len(column_names))

    excludes = []

    if excluded_columns:
        for c in excluded_columns.split(','):
            try:
                excludes.append(match_column_identifier(column_names, c, column_offset))
            except ColumnIdentifierError:
                if ':' in c:
                    a, b = c.split(':', 1)
                elif '-' in c:
                    a, b = c.split('-', 1)
                else:
                    raise

                try:
                    a = int(a) if a else 1
                    b = int(b) + 1 if b else len(column_names)
                except ValueError:
                    raise ColumnIdentifierError(
                        "Invalid range %s. Ranges must be two integers separated by a - or : character.")

                for x in range(a, b):
                    excludes.append(match_column_identifier(column_names, x, column_offset))

    return [c for c in columns if c not in excludes]

def __init__(self, args, column_names):
    self.args = args
    self.column_names = column_names

    self.lat_column = match_column_identifier(column_names, self.args.lat, self.args.zero_based)

    self.lon_column = match_column_identifier(column_names, self.args.lon, self.args.zero_based)

    if self.args.type:
        self.type_column = match_column_identifier(column_names, self.args.type, self.args.zero_based)
    else:
        self.type_column = None

    if self.args.geometry:
        self.geometry_column = match_column_identifier(column_names, self.args.geometry, self.args.zero_based)
    else:
        self.geometry_column = None

    if self.args.key:
        self.id_column = match_column_identifier(column_names, self.args.key, self.args.zero_based)
    else:
        self.id_column = None

def __next__(self):
    if self.column_names and not self.returned_header:
        self.returned_header = True
        return self.column_names

    while True:
        row = next(self.reader)

        if self.test_row(row):
            return row

    raise StopIteration()

def test_row(self, row):
    for idx, test in self.patterns.items():
        try:
            value = row[idx]
        except IndexError:
            value = ''
        result = test(value)
        if self.any_match:
            if result:
                return not self.inverse  # True
        else:
            if not result:
                return self.inverse  # False

    if self.any_match:
        return self.inverse  # False
    return not self.inverse  # True

def _skip_lines(f, args):
    if isinstance(args.skip_lines, int):
        skip_lines = args.skip_lines
        while skip_lines > 0:
            f.readline()
            skip_lines -= 1
    else:
        raise ValueError('skip_lines argument must be an int')

    return skip_lines

def __next__(self):
    if self.header:
        self.header = False
        return self.parser.headers

    return self.parser.parse(next(self.file))

def parse(self, line):
    values = []

    for field in self.fields:
        values.append(line[field.start:field.start + field.length].strip())

    return values

def parse_dict(self, line):
    """
    Convenience method returns a dict. Equivalent to
    ``dict(zip(self.headers,self.parse(line)))``.
    """
    return dict(zip(self.headers, self.parse(line)))

def __init__(self, f, schema, encoding=None):
    if encoding is not None:
        f = iterdecode(f, encoding)

    self.file = f
    self.parser = FixedWidthRowParser(schema)
    self.header = True

def __init__(self, schema):
    self.fields = []  # A list of FixedWidthFields

    schema_reader = agate.csv.reader(schema)
    schema_decoder = SchemaDecoder(next(schema_reader))

    for i, row in enumerate(schema_reader):
        try:
            self.fields.append(schema_decoder(row))
        except Exception as e:
            raise ValueError("Error reading schema at line %i: %s" % (i + 2, e))

def _extract_csv_writer_kwargs(self):
    kwargs = {}

    if self.args.line_numbers:
        kwargs['line_numbers'] = True

    if self.args.out_tabs:
        kwargs['delimiter'] = '\t'
    elif self.args.out_delimiter:
        kwargs['delimiter'] = self.args.out_delimiter

    for arg in ('quotechar', 'quoting', 'doublequote', 'escapechar', 'lineterminator'):
        value = getattr(self.args, f'out_{arg}')
        if value is not None:
            kwargs[arg] = value

    return kwargs

def _parse_join_column_names(self, join_string):
    """
    Parse a list of join columns.
    """
    return list(map(str.strip, join_string.split(',')))

def _calculate_stat(self, table, column_id, op_name, op_data, **kwargs):
    getter = globals().get(f'get_{op_name}')

    with warnings.catch_warnings():
        warnings.simplefilter('ignore', agate.NullCalculationWarning)

        try:
            if getter:
                return getter(table, column_id, **kwargs)

            op = op_data['aggregation']
            v = table.aggregate(op(column_id))

            if self.is_finite_decimal(v) and not self.args.json_output:
                return format_decimal(v, self.args.decimal_format, self.args.no_grouping_separator)

            return v
        except Exception:
            pass

def calculate_stats(self, table, column_id, **kwargs):
    """
    Calculate stats for all valid operations.
    """
    return {
        op_name: self._calculate_stat(table, column_id, op_name, op_data, **kwargs)
        for op_name, op_data in OPERATIONS.items()
    }

def print_stats(self, table, column_ids, stats):
    """
    Print data for all statistics.
    """
    label_column_width = max(len(op_data['label']) for op_data in OPERATIONS.values())

    for column_id in column_ids:
        column_name = table.column_names[column_id]
        column = table.columns[column_id]
        column_stats = stats[column_id]

        self.output_file.write('%3i. "%s"\n\n' % (column_id + 1, column_name))

        for op_name, op_data in OPERATIONS.items():
            if column_stats[op_name] is None:
                continue

            label = '{label:{label_column_width}}'.format(**{
                'label_column_width': label_column_width,
                'label': op_data['label'],
            })

            if op_name == 'freq':
                for i, row in enumerate(column_stats['freq']):
                    if i == 0:
                        self.output_file.write(f'\t{label} ')
                    else:
                        self.output_file.write('\t{label:{label_column_width}} '.format(**{
                            'label_column_width': label_column_width,
                            'label': '',
                        }))

                    if isinstance(column.data_type, agate.Number):
                        v = row['value']

                        if self.is_finite_decimal(v):
                            v = format_decimal(v, self.args.decimal_format, self.args.no_grouping_separator)
                    else:
                        v = str(row['value'])

                    self.output_file.write(f"{v} ({row['count']}x)\n")

                continue

            v = column_stats[op_name]

            if op_name == 'nulls' and v:
                v = f'{v} (excluded from calculations)'
            elif op_name == 'len':
                v = f'{v} characters'

            self.output_file.write(f'\t{label} {v}\n')

        self.output_file.write('\n')

    self.output_file.write(f'Row count: {len(table.rows)}\n')

def get_freq(table, column_id, freq_count=5, **kwargs):
    values = table.columns[column_id].values()
    return [
        {'value': r[0], 'count': r[1]}
        for r in Counter(values).most_common(freq_count)
    ]

def _rows(self, table, column_ids, stats):
    for column_id in column_ids:
        column_name = table.column_names[column_id]
        column_stats = stats[column_id]

        output_row = {'column_id': column_id + 1, 'column_name': column_name}
        for op_name, _op_data in OPERATIONS.items():
            if column_stats[op_name] is not None:
                output_row[op_name] = column_stats[op_name]

        yield output_row

def main(self):
    """
    Convert CSV to JSON.
    """
    if self.args.lat and not self.args.lon:
        self.argparser.error('--lon is required whenever --lat is specified.')
    if self.args.lon and not self.args.lat:
        self.argparser.error('--lat is required whenever --lon is specified.')

    if self.args.crs and not self.args.lat:
        self.argparser.error('--crs is only allowed when --lat and --lon are also specified.')
    if self.args.type and not self.args.lat:
        self.argparser.error('--type is only allowed when --lat and --lon are also specified.')
    if self.args.geometry and not self.args.lat:
        self.argparser.error('--geometry is only allowed when --lat and --lon are also specified.')

    if self.args.key and self.args.streamOutput and not (self.args.lat and self.args.lon):
        self.argparser.error('--key is only allowed with --stream when --lat and --lon are also specified.')

    self.json_kwargs = {
        'indent': self.args.indent,
    }

    if self.can_stream():
        if self.additional_input_expected():
            sys.stderr.write('No input file or piped data provided. Waiting for standard input:\n')

        if self.is_geo():
            self.streaming_output_ndgeojson()
        else:
            self.streaming_output_ndjson()

    else:
        if self.additional_input_expected():
            self.argparser.error('You must provide an input file or piped data.')

        if self.is_geo():
            self.output_geojson()
        else:
            self.output_json()

def dump_json(self, data, newline=False):
    json.dump(data, self.output_file, default=default_str_decimal, ensure_ascii=False, **self.json_kwargs)
    if newline:
        self.output_file.write("\n")

def can_stream(self):
    return (
        self.args.streamOutput
        and self.args.no_inference
        and self.args.sniff_limit == 0
        and not self.args.skip_lines
    )

def read_csv_to_table(self):
    sniff_limit = self.args.sniff_limit if self.args.sniff_limit != -1 else None
    return agate.Table.from_csv(
        self.input_file,
        skip_lines=self.args.skip_lines,
        sniff_limit=sniff_limit,
        column_types=self.get_column_types(),
        **self.reader_kwargs,
    )

def output_geojson(self):
    table = self.read_csv_to_table()
    geojson_generator = self.GeoJsonGenerator(self.args, table.column_names)

    if self.args.streamOutput:
        for row in table.rows:
            self.dump_json(geojson_generator.feature_for_row(row), newline=True)
    else:
        self.dump_json(geojson_generator.generate_feature_collection(table))

def streaming_output_ndjson(self):
    rows = agate.csv.reader(self.input_file, **self.reader_kwargs)
    column_names = next(rows)

    for row in rows:
        data = OrderedDict()
        for i, column in enumerate(column_names):
            try:
                data[column] = row[i]
            except IndexError:
                data[column] = None
        self.dump_json(data, newline=True)

def streaming_output_ndgeojson(self):
    rows = agate.csv.reader(self.input_file, **self.reader_kwargs)
    column_names = next(rows)
    geojson_generator = self.GeoJsonGenerator(self.args, column_names)

    for row in rows:
        self.dump_json(geojson_generator.feature_for_row(row), newline=True)

def add_feature(self, feature):
    if 'geometry' in feature and 'coordinates' in feature['geometry']:
        self.update_coordinates(feature['geometry']['coordinates'])

def update_lat(self, lat):
    if self.min_lat is None or lat < self.min_lat:
        self.min_lat = lat
    if self.max_lat is None or lat > self.max_lat:
        self.max_lat = lat

def update_lon(self, lon):
    if self.min_lon is None or lon < self.min_lon:
        self.min_lon = lon
    if self.max_lon is None or lon > self.max_lon:
        self.max_lon = lon

def update_coordinates(self, coordinates):
    if len(coordinates) <= 3 and isinstance(coordinates[0], (float, int)):
        self.update_lon(coordinates[0])
        self.update_lat(coordinates[1])
    else:
        for coordinate in coordinates:
            self.update_coordinates(coordinate)
